insert into public.articles ("id","title","category","author","authorOpenId","summary","date","updated","status","views","image","bodyHtml","scheduledAt","tags","youtubeUrl","socialLinks","slug","seoTitle","metaDescription","canonicalUrl","focusKeyword","ogTitle","ogDescription","imageAlt","noindex","createdAt","updatedAt","scope","region","state","country","language","featured","sourceUrl","sourceName","contentType","editorialChecklist","editorialNotes","contraponto","keyTakeaway","editionNumber","authorProfileSlug") values ('evaldo-pilula-01-a-luz-que-ainda-existe','A Luz que Ainda Existe','Colunas','Evaldo Poeta',NULL,'Nem toda luz desaparece. Às vezes, ela só espera que você retire o que a cobre.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Nem toda luz desaparece. Às vezes, ela só espera que você retire o que a cobre.</p><div class="pilula-poeta">Há uma luz dentro de você<br />que o medo não conseguiu apagar.<br />Talvez a vida tenha feito sombra,<br />mas sombra não é fim: é só falta de claridade.<br />Há dias em que a vergonha pesa,<br />o passado tenta falar mais alto,<br />e o coração quase acredita<br />que nasceu para viver escondido.<br />Mas talvez Deus não esteja pedindo perfeição.<br />Talvez esteja pedindo presença.<br />Pare um instante, escute,<br />e perceba que ainda existe luz aí.<br />A pergunta não é se você tem luz.<br />É: o que está impedindo essa luz de aparecer?</div><hr /><p><strong>Reflexão:</strong> O que está cobrindo a sua luz hoje?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-01-a-luz-que-ainda-existe','A Luz que Ainda Existe | Pílula do Poeta','Nem toda luz desaparece. Às vezes, ela só espera que você retire o que a cobre. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 3 / 40>',NULL,'a luz que ainda existe','A Luz que Ainda Existe | Pílula do Poeta','Nem toda luz desaparece. Às vezes, ela só espera que você retire o que a cobre. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 3 / 40>','Arte da Pílula do Poeta 01: A Luz que Ainda Existe',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',true,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,1,'evaldo-poeta'),('evaldo-pilula-02-lave-os-olhos','Lave os Olhos','Colunas','Evaldo Poeta',NULL,'Antes de querer mostrar o caminho, talvez seja preciso aprender a enxergar.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Antes de querer mostrar o caminho, talvez seja preciso aprender a enxergar.</p><div class="pilula-poeta">Há quem queira falar muito,<br />mas ainda não aprendeu a escutar.<br />Há quem queira ensinar caminhos,<br />mas ainda não parou para olhar.<br />A humildade não diminui ninguém.<br />Ela abre espaço para aprender.<br />Quem escuta com o coração<br />enxerga aquilo que o orgulho não deixa ver.<br />Talvez você não precise de uma resposta nova.<br />Talvez precise de olhos novos.<br />Um olhar disposto a perceber<br />o que antes passava despercebido.<br />Porque quem aprende a enxergar diferente<br />também começa a caminhar diferente.</div><hr /><p><strong>Reflexão:</strong> O que você precisa enxergar de outro jeito hoje?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-02-lave-os-olhos','Lave os Olhos | Pílula do Poeta','Antes de querer mostrar o caminho, talvez seja preciso aprender a enxergar. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 4 / 40>',NULL,'lave os olhos','Lave os Olhos | Pílula do Poeta','Antes de querer mostrar o caminho, talvez seja preciso aprender a enxergar. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 4 / 40>','Arte da Pílula do Poeta 02: Lave os Olhos',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',true,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,2,'evaldo-poeta'),('evaldo-pilula-03-o-brilho-escondido','O Brilho Escondido','Colunas','Evaldo Poeta',NULL,'Existe valor em você que talvez a dor tenha escondido, mas não destruído.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Existe valor em você que talvez a dor tenha escondido, mas não destruído.</p><div class="pilula-poeta">Existe um brilho escondido<br />por trás de algumas cicatrizes.<br />Há tesouros que não aparecem<br />na primeira vez que olhamos.<br />A dor pode cobrir uma janela,<br />mas não consegue apagar o céu.<br />O silêncio pode esconder uma voz,<br />mas não consegue destruir sua história.<br />Talvez você esteja procurando fora<br />aquilo que precisa primeiro reconhecer dentro.<br />Não para se achar perfeito,<br />mas para lembrar que ainda há vida em você.<br />Às vezes, despertar<br />é simplesmente retirar o véu<br />e reconhecer o que sempre esteve ali.</div><hr /><p><strong>Reflexão:</strong> Que parte bonita de você a dor fez esquecer?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-03-o-brilho-escondido','O Brilho Escondido | Pílula do Poeta','Existe valor em você que talvez a dor tenha escondido, mas não destruído. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 5 / 40>',NULL,'o brilho escondido','O Brilho Escondido | Pílula do Poeta','Existe valor em você que talvez a dor tenha escondido, mas não destruído. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 5 / 40>','Arte da Pílula do Poeta 03: O Brilho Escondido',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',true,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,3,'evaldo-poeta'),('evaldo-pilula-04-pegue-o-interruptor','Pegue o Interruptor','Colunas','Evaldo Poeta',NULL,'Não entregue a outra pessoa o comando daquilo que você precisa escolher.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Não entregue a outra pessoa o comando daquilo que você precisa escolher.</p><div class="pilula-poeta">A vida pode apagar algumas luzes,<br />mas não precisa levar o interruptor.<br />Há coisas que aconteceram com você<br />que não precisam decidir quem você será.<br />Alguém pode ter ferido,<br />rejeitado ou diminuído você.<br />Mas o passado explica algumas marcas;<br />não precisa escrever todas as próximas páginas.<br />Retomar o comando não é negar o que aconteceu.<br />É reconhecer o que aconteceu<br />sem entregar a ele o volante.<br />Talvez hoje seja o dia<br />de acender novamente uma luz.<br />Não porque tudo ficou fácil,<br />mas porque você decidiu voltar a participar da própria história.</div><hr /><p><strong>Reflexão:</strong> Que decisão você precisa voltar a assumir?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-04-pegue-o-interruptor','Pegue o Interruptor | Pílula do Poeta','Não entregue a outra pessoa o comando daquilo que você precisa escolher. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 6 / 40>',NULL,'pegue o interruptor','Pegue o Interruptor | Pílula do Poeta','Não entregue a outra pessoa o comando daquilo que você precisa escolher. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 6 / 40>','Arte da Pílula do Poeta 04: Pegue o Interruptor',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',true,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,4,'evaldo-poeta'),('evaldo-pilula-05-de-voz-a-fe','Dê Voz à Fé','Colunas','Evaldo Poeta',NULL,'Há momentos em que a fé precisa deixar de ser apenas pensamento e ganhar voz.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Há momentos em que a fé precisa deixar de ser apenas pensamento e ganhar voz.</p><div class="pilula-poeta">No meio da multidão,<br />uma voz pode parecer pequena.<br />Mas quem sabe o que procura<br />não precisa gritar para impressionar.<br />Às vezes, você sabe o que precisa pedir,<br />mas o medo manda ficar calado.<br />A vergonha segura a palavra,<br />e a dúvida tenta convencer você a desistir.<br />Bartimeu nos lembra de uma atitude:<br />há momentos em que a fé precisa ser expressa.<br />Não para provar algo aos outros,<br />mas para reconhecer diante de Deus aquilo que o coração deseja.<br />Talvez sua próxima mudança comece<br />quando aquilo que você sente<br />finalmente encontrar uma voz.</div><hr /><p><strong>Reflexão:</strong> O que você precisa ter coragem de colocar em palavras?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-05-de-voz-a-fe','Dê Voz à Fé | Pílula do Poeta','Há momentos em que a fé precisa deixar de ser apenas pensamento e ganhar voz. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 7 / 40>',NULL,'dê voz à fé','Dê Voz à Fé | Pílula do Poeta','Há momentos em que a fé precisa deixar de ser apenas pensamento e ganhar voz. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 7 / 40>','Arte da Pílula do Poeta 05: Dê Voz à Fé',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',true,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,5,'evaldo-poeta'),('evaldo-pilula-06-dom-sem-amor','Dom sem Amor','Colunas','Evaldo Poeta',NULL,'Talento pode chamar atenção. Amor é o que dá sentido ao talento.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Talento pode chamar atenção. Amor é o que dá sentido ao talento.</p><div class="pilula-poeta">Você pode ter voz,<br />habilidade, inteligência e força.<br />Pode fazer muito,<br />ser reconhecido e chegar longe.<br />Mas todo dom carrega uma pergunta:<br />para quê?<br />Porque talento sem propósito<br />pode virar apenas barulho.<br />Quando o conhecimento encontra o amor,<br />o que você sabe começa a servir.<br />Quando a capacidade encontra cuidado,<br />o talento deixa de ser vitrine<br />e se transforma em presença.<br />Não é apenas sobre o que você consegue fazer.<br />É sobre o bem que pode nascer<br />quando você decide fazer com amor.</div><hr /><p><strong>Reflexão:</strong> Seu talento está servindo apenas a você ou também a alguém?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-06-dom-sem-amor','Dom sem Amor | Pílula do Poeta','Talento pode chamar atenção. Amor é o que dá sentido ao talento. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 8 / 40>',NULL,'dom sem amor','Dom sem Amor | Pílula do Poeta','Talento pode chamar atenção. Amor é o que dá sentido ao talento. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 8 / 40>','Arte da Pílula do Poeta 06: Dom sem Amor',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,6,'evaldo-poeta'),('evaldo-pilula-07-quando-a-palavra-ganha-vida','Quando a Palavra Ganha Vida','Colunas','Evaldo Poeta',NULL,'Escrever não é apenas colocar palavras no papel. Às vezes, é dar forma ao que estava 
confuso por dentro.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Escrever não é apenas colocar palavras no papel. Às vezes, é dar forma ao que estava 
confuso por dentro.</p><div class="pilula-poeta">Há pensamentos que ficam presos<br />porque ainda não encontraram palavras.<br />Há sentimentos que parecem enormes<br />até que alguém consegue escrevê-los.<br />Quando escrevemos,<br />o silêncio ganha contorno.<br />O caos encontra uma linha.<br />E aquilo que parecia impossível de explicar<br />começa a ser compreendido.<br />Talvez por isso algumas palavras<br />nos libertem antes mesmo de serem lidas por alguém.<br />Elas organizam quem escreve.<br />Pegue uma folha.<br />Comece sem perfeição.<br />Às vezes, uma frase é o primeiro passo<br />para entender uma história inteira.</div><hr /><p><strong>Reflexão:</strong> Que pensamento dentro de você precisa ganhar palavras?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-07-quando-a-palavra-ganha-vida','Quando a Palavra Ganha Vida | Pílula do Poeta','Escrever não é apenas colocar palavras no papel. Às vezes, é dar forma ao que estava confuso por dentro. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 10 / 40>',NULL,'quando a palavra ganha vida','Quando a Palavra Ganha Vida | Pílula do Poeta','Escrever não é apenas colocar palavras no papel. Às vezes, é dar forma ao que estava confuso por dentro. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 10 / 40>','Arte da Pílula do Poeta 07: Quando a Palavra Ganha Vida',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,7,'evaldo-poeta'),('evaldo-pilula-08-um-proposito-maior','Um Propósito Maior','Colunas','Evaldo Poeta',NULL,'Nem todo chamado faz barulho. Alguns chegam como uma inquietação silenciosa que 
insiste em permanecer.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Nem todo chamado faz barulho. Alguns chegam como uma inquietação silenciosa que 
insiste em permanecer.</p><div class="pilula-poeta">Há caminhos que parecem comuns,<br />mas carregam um propósito.<br />Há tarefas pequenas<br />que podem tocar vidas grandes.<br />Propósito não é apenas aparecer.<br />É saber por que você continua<br />quando ninguém está olhando.<br />Talvez sua vida não esteja pedindo<br />uma plateia maior.<br />Talvez esteja pedindo<br />uma entrega mais verdadeira.<br />Quando você entende para que caminha,<br />até os passos pequenos<br />começam a ter direção.</div><hr /><p><strong>Reflexão:</strong> O que hoje você faz que poderia ganhar um propósito maior?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-08-um-proposito-maior','Um Propósito Maior | Pílula do Poeta','Nem todo chamado faz barulho. Alguns chegam como uma inquietação silenciosa que insiste em permanecer. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 11 / 40>',NULL,'um propósito maior','Um Propósito Maior | Pílula do Poeta','Nem todo chamado faz barulho. Alguns chegam como uma inquietação silenciosa que insiste em permanecer. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 11 / 40>','Arte da Pílula do Poeta 08: Um Propósito Maior',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,8,'evaldo-poeta'),('evaldo-pilula-09-qual-voz-voce-alimenta','Qual Voz Você Alimenta?','Colunas','Evaldo Poeta',NULL,'Dentro de nós existe barulho suficiente. A questão é: qual voz merece nossa atenção?','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Dentro de nós existe barulho suficiente. A questão é: qual voz merece nossa atenção?</p><div class="pilula-poeta">Há vozes que aceleram,<br />vozes que assustam,<br />vozes que dizem que não vai dar.<br />E há uma voz mais serena,<br />que não precisa gritar<br />para ser ouvida.<br />Nem todo pensamento merece ser obedecido.<br />Nem toda urgência é direção.<br />Nem todo medo é aviso.<br />Talvez maturidade também seja isso:<br />aprender a distinguir<br />o barulho daquilo que traz paz.<br />Antes de seguir qualquer voz,<br />pare.<br />Escute.<br />Pergunte de onde ela vem<br />e para onde ela está levando você.</div><hr /><p><strong>Reflexão:</strong> Qual voz tem ocupado espaço demais dentro de você?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-09-qual-voz-voce-alimenta','Qual Voz Você Alimenta? | Pílula do Poeta','Dentro de nós existe barulho suficiente. A questão é: qual voz merece nossa atenção? Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 13 / 40>',NULL,'qual voz você alimenta?','Qual Voz Você Alimenta? | Pílula do Poeta','Dentro de nós existe barulho suficiente. A questão é: qual voz merece nossa atenção? Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 13 / 40>','Arte da Pílula do Poeta 09: Qual Voz Você Alimenta?',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,9,'evaldo-poeta'),('evaldo-pilula-10-sua-historia-tem-valor','Sua História Tem Valor','Colunas','Evaldo Poeta',NULL,'Você não é apenas aquilo que aconteceu. Sua história também é aquilo que você escolhe
fazer com o que viveu.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Você não é apenas aquilo que aconteceu. Sua história também é aquilo que você 
escolhe fazer com o que viveu.</p><div class="pilula-poeta">Sua história tem capítulos<br />que talvez você preferisse esconder.<br />Mas até as páginas difíceis<br />fazem parte daquilo que você se tornou.<br />Não é preciso romantizar a dor.<br />Nem fingir que tudo foi fácil.<br />É possível reconhecer as feridas<br />e ainda escolher continuar.<br />Talvez o seu passado<br />não seja uma sentença,<br />mas uma parte da narrativa.<br />E quando você aprende a olhar para trás<br />sem morar lá,<br />a história deixa de ser prisão<br />e começa a se transformar em testemunho.</div><hr /><p><strong>Reflexão:</strong> O que você viveu pode ensinar algo que hoje pode servir a alguém?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-10-sua-historia-tem-valor','Sua História Tem Valor | Pílula do Poeta','Você não é apenas aquilo que aconteceu. Sua história também é aquilo que você escolhe fazer com o que viveu. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 14 / 40>',NULL,'sua história tem valor','Sua História Tem Valor | Pílula do Poeta','Você não é apenas aquilo que aconteceu. Sua história também é aquilo que você escolhe fazer com o que viveu. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 14 / 40>','Arte da Pílula do Poeta 10: Sua História Tem Valor',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,10,'evaldo-poeta'),('evaldo-pilula-11-o-que-voce-deixa','O Que Você Deixa?','Colunas','Evaldo Poeta',NULL,'O tempo pergunta silenciosamente: depois que você passar, o que permanecerá nas 
pessoas?','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">O tempo pergunta silenciosamente: depois que você passar, o que permanecerá nas 
pessoas?</p><div class="pilula-poeta">O relógio continua andando<br />mesmo quando ninguém percebe.<br />Os dias passam sem pedir licença.<br />No fim, quase ninguém será lembrado<br />pelo tamanho daquilo que acumulou,<br />mas pelo impacto daquilo que ofereceu.<br />Uma palavra pode permanecer.<br />Um abraço pode permanecer.<br />Uma oportunidade dada<br />pode permanecer.<br />Talvez legado não seja deixar coisas.<br />Talvez seja deixar marcas<br />que façam alguém caminhar melhor.</div><hr /><p><strong>Reflexão:</strong> Que marca você gostaria de deixar nas pessoas que cruzam sua vida?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-11-o-que-voce-deixa','O Que Você Deixa? | Pílula do Poeta','O tempo pergunta silenciosamente: depois que você passar, o que permanecerá nas pessoas? Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 15 / 40>',NULL,'o que você deixa?','O Que Você Deixa? | Pílula do Poeta','O tempo pergunta silenciosamente: depois que você passar, o que permanecerá nas pessoas? Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 15 / 40>','Arte da Pílula do Poeta 11: O Que Você Deixa?',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,11,'evaldo-poeta'),('evaldo-pilula-12-transforme-a-ponte','Transforme a Ponte','Colunas','Evaldo Poeta',NULL,'Algumas crises parecem muros, até o dia em que percebemos que também podem se 
tornar passagem.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Algumas crises parecem muros, até o dia em que percebemos que também podem se 
tornar passagem.</p><div class="pilula-poeta">Há dores que chegam<br />parecendo o fim de uma estrada.<br />Mas nem toda ruptura é destino final.<br />Às vezes, aquilo que nos quebra<br />também revela caminhos<br />que nunca teríamos procurado.<br />Não precisamos chamar a dor de boa<br />para reconhecer que podemos aprender com ela.<br />Não precisamos negar a queda<br />para voltar a caminhar.<br />Talvez a pergunta não seja:<br />“Por que isso aconteceu comigo?”<br />Talvez também seja:<br />“Que caminho posso construir a partir daqui?”</div><hr /><p><strong>Reflexão:</strong> Que experiência difícil pode se transformar em aprendizado para o seu próximo passo?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-12-transforme-a-ponte','Transforme a Ponte | Pílula do Poeta','Algumas crises parecem muros, até o dia em que percebemos que também podem se tornar passagem. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 16 / 40>',NULL,'transforme a ponte','Transforme a Ponte | Pílula do Poeta','Algumas crises parecem muros, até o dia em que percebemos que também podem se tornar passagem. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 16 / 40>','Arte da Pílula do Poeta 12: Transforme a Ponte',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,12,'evaldo-poeta'),('evaldo-pilula-13-cuide-de-si','Cuide de Si','Colunas','Evaldo Poeta',NULL,'Amar o outro sem se abandonar também pode ser uma forma de esquecer que você 
existe.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Amar o outro sem se abandonar também pode ser uma forma de esquecer que você 
existe.</p><div class="pilula-poeta">Você aprendeu a cuidar,<br />a ajudar,<br />a estar presente.<br />Mas quem cuida de você<br />quando você se deixa sempre por último?<br />Amor próprio não é colocar-se acima dos outros.<br />É reconhecer que você também merece cuidado,<br />respeito e descanso.<br />Quem conhece o próprio valor<br />não precisa diminuir ninguém.<br />E quem se trata com dignidade<br />aprende a oferecer dignidade com mais verdade.<br />Não se abandone<br />enquanto tenta salvar todos ao redor.</div><hr /><p><strong>Reflexão:</strong> Em que área da sua vida você precisa voltar a cuidar de si?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-13-cuide-de-si','Cuide de Si | Pílula do Poeta','Amar o outro sem se abandonar também pode ser uma forma de esquecer que você existe. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 17 / 40>',NULL,'cuide de si','Cuide de Si | Pílula do Poeta','Amar o outro sem se abandonar também pode ser uma forma de esquecer que você existe. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 17 / 40>','Arte da Pílula do Poeta 13: Cuide de Si',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,13,'evaldo-poeta'),('evaldo-pilula-14-volte-para-casa','Volte para Casa','Colunas','Evaldo Poeta',NULL,'Há momentos em que voltar não é fracassar. É reconhecer onde o coração precisa estar.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Há momentos em que voltar não é fracassar. É reconhecer onde o coração precisa 
estar.</p><div class="pilula-poeta">Você pode errar.<br />Pode se afastar.<br />Pode tomar caminhos que depois gostaria de refazer.<br />Mas um erro não precisa ser<br />a última palavra da sua história.<br />Há portas que permanecem abertas<br />mesmo depois da distância.<br />Há braços que não precisam<br />de uma explicação perfeita para acolher.<br />Voltar exige humildade.<br />E às vezes a maior coragem<br />não é seguir adiante,<br />mas reconhecer que precisamos retornar.<br />Talvez hoje seja dia de voltar<br />para aquilo que realmente importa.</div><hr /><p><strong>Reflexão:</strong> Existe algum lugar, pessoa ou propósito para o qual seu coração está pedindo retorno?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-14-volte-para-casa','Volte para Casa | Pílula do Poeta','Há momentos em que voltar não é fracassar. É reconhecer onde o coração precisa estar. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 18 / 40>',NULL,'volte para casa','Volte para Casa | Pílula do Poeta','Há momentos em que voltar não é fracassar. É reconhecer onde o coração precisa estar. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 18 / 40>','Arte da Pílula do Poeta 14: Volte para Casa',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,14,'evaldo-poeta'),('evaldo-pilula-15-a-graca-muda-o-olhar','A Graça Muda o Olhar','Colunas','Evaldo Poeta',NULL,'Às vezes, não precisamos mudar o mundo primeiro. Precisamos mudar a maneira 
como o enxergamos.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Às vezes, não precisamos mudar o mundo primeiro. Precisamos mudar a maneira 
como o enxergamos.</p><div class="pilula-poeta">A mesma estrada pode parecer pesada<br />quando o coração está cansado.<br />A mesma vida pode parecer diferente<br />quando o olhar encontra esperança.<br />A graça não apaga a realidade.<br />Mas pode mudar a forma<br />como atravessamos a realidade.<br />Quando o coração se abre,<br />a visão se amplia.<br />O que parecia apenas problema<br />pode revelar uma possibilidade.<br />Talvez a transformação comece<br />não no cenário,<br />mas no olhar que você leva para ele.</div><hr /><p><strong>Reflexão:</strong> O que poderia mudar se você olhasse para sua situação com mais esperança?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-15-a-graca-muda-o-olhar','A Graça Muda o Olhar | Pílula do Poeta','Às vezes, não precisamos mudar o mundo primeiro. Precisamos mudar a maneira como o enxergamos. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 19 / 40>',NULL,'a graça muda o olhar','A Graça Muda o Olhar | Pílula do Poeta','Às vezes, não precisamos mudar o mundo primeiro. Precisamos mudar a maneira como o enxergamos. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 19 / 40>','Arte da Pílula do Poeta 15: A Graça Muda o Olhar',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,15,'evaldo-poeta'),('evaldo-pilula-16-pense-antes-de-prender-se','Pense Antes de Prender-se','Colunas','Evaldo Poeta',NULL,'Nem todo pedido merece um sim. Pensar também é uma forma de liberdade.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Nem todo pedido merece um sim. Pensar também é uma forma de liberdade.</p><div class="pilula-poeta">Há pessoas que dizem sim<br />quando gostariam de dizer não.<br />Há escolhas feitas por medo<br />de decepcionar alguém.<br />Mas concordar com tudo<br />também pode ser uma forma de se abandonar.<br />Pensar não é desrespeitar.<br />Questionar não é rebelar-se.<br />Estabelecer limites não é deixar de amar.<br />A liberdade começa quando você percebe<br />que pode refletir antes de responder.<br />Nem toda porta que alguém aponta<br />é uma porta que você precisa atravessar.</div><hr /><p><strong>Reflexão:</strong> Em qual situação você precisa pensar antes de simplesmente dizer sim?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-16-pense-antes-de-prender-se','Pense Antes de Prender-se | Pílula do Poeta','Nem todo pedido merece um sim. Pensar também é uma forma de liberdade. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 20 / 40>',NULL,'pense antes de prender-se','Pense Antes de Prender-se | Pílula do Poeta','Nem todo pedido merece um sim. Pensar também é uma forma de liberdade. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 20 / 40>','Arte da Pílula do Poeta 16: Pense Antes de Prender-se',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,16,'evaldo-poeta'),('evaldo-pilula-17-pare-de-esperar-o-momento-perfeito','Pare de Esperar o Momento Perfeito','Colunas','Evaldo Poeta',NULL,'O medo adora vestir a roupa do perfeccionismo.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">O medo adora vestir a roupa do perfeccionismo.</p><div class="pilula-poeta">Você espera a hora certa,<br />a coragem certa,<br />a condição certa.<br />Enquanto isso,<br />a vida continua acontecendo.<br />O perfeccionismo promete segurança,<br />mas muitas vezes entrega adiamento.<br />Ele diz: “prepare-se mais um pouco”.<br />E o tempo responde: “comece”.<br />Não é preciso começar perfeito.<br />É preciso começar consciente,<br />aprender no caminho<br />e continuar ajustando os passos.<br />Às vezes, o primeiro movimento<br />é exatamente o que faltava<br />para o segundo aparecer.</div><hr /><p><strong>Reflexão:</strong> O que você está adiando porque ainda não se sente preparado?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-17-pare-de-esperar-o-momento-perfeito','Pare de Esperar o Momento Perfeito | Pílula do Poeta','O medo adora vestir a roupa do perfeccionismo. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 21 / 40>',NULL,'pare de esperar o momento perfeito','Pare de Esperar o Momento Perfeito | Pílula do Poeta','O medo adora vestir a roupa do perfeccionismo. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 21 / 40>','Arte da Pílula do Poeta 17: Pare de Esperar o Momento Perfeito',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,17,'evaldo-poeta'),('evaldo-pilula-18-seu-tempo-tem-valor','Seu Tempo Tem Valor','Colunas','Evaldo Poeta',NULL,'O dia de hoje parece pequeno, até você perceber que ele nunca mais voltará.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">O dia de hoje parece pequeno, até você perceber que ele nunca mais voltará.</p><div class="pilula-poeta">Cada manhã chega<br />com uma quantidade limitada de horas.<br />E nenhuma delas pode ser guardada<br />para amanhã.<br />O tempo não faz barulho<br />quando vai embora.<br />Ele simplesmente passa.<br />Por isso, algumas perguntas são necessárias:<br />o que merece minha atenção?<br />o que estou adiando?<br />o que estou gastando<br />que não gostaria de perder?<br />Talvez administrar o tempo<br />seja, no fundo,<br />aprender a administrar a própria vida.</div><hr /><p><strong>Reflexão:</strong> Se hoje fosse uma página única, o que você gostaria de escrever nela?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-18-seu-tempo-tem-valor','Seu Tempo Tem Valor | Pílula do Poeta','O dia de hoje parece pequeno, até você perceber que ele nunca mais voltará. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 22 / 40>',NULL,'seu tempo tem valor','Seu Tempo Tem Valor | Pílula do Poeta','O dia de hoje parece pequeno, até você perceber que ele nunca mais voltará. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 22 / 40>','Arte da Pílula do Poeta 18: Seu Tempo Tem Valor',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,18,'evaldo-poeta'),('evaldo-pilula-19-o-espelho-nao-conta-tudo','O Espelho Não Conta Tudo','Colunas','Evaldo Poeta',NULL,'O espelho mostra uma aparência. Ele não conhece toda a história que existe por trás 
dela.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">O espelho mostra uma aparência. Ele não conhece toda a história que existe por trás 
dela.</p><div class="pilula-poeta">Você olha para o espelho<br />e encontra um rosto.<br />Mas ali também existem histórias,<br />medos, sonhos e recomeços.<br />O problema começa<br />quando uma imagem vira sentença.<br />Quando um detalhe passa a definir<br />toda a pessoa.<br />Você é maior que aquilo<br />que consegue enxergar em alguns segundos.<br />Olhe novamente.<br />Não apenas para o que falta,<br />mas para aquilo que permanece.<br />Talvez exista mais força em você<br />do que o reflexo conseguiu mostrar.</div><hr /><p><strong>Reflexão:</strong> Quando você se olha, enxerga apenas aparência ou também reconhece sua história e seu valor?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-19-o-espelho-nao-conta-tudo','O Espelho Não Conta Tudo | Pílula do Poeta','O espelho mostra uma aparência. Ele não conhece toda a história que existe por trás dela. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 23 / 40>',NULL,'o espelho não conta tudo','O Espelho Não Conta Tudo | Pílula do Poeta','O espelho mostra uma aparência. Ele não conhece toda a história que existe por trás dela. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 23 / 40>','Arte da Pílula do Poeta 19: O Espelho Não Conta Tudo',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,19,'evaldo-poeta'),('evaldo-pilula-20-o-chamado-no-meio-da-rotina','O Chamado no Meio da Rotina','Colunas','Evaldo Poeta',NULL,'Algumas mudanças começam no lugar mais comum: no meio de um dia que parecia 
igual a todos os outros.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Algumas mudanças começam no lugar mais comum: no meio de um dia que parecia 
igual a todos os outros.</p><div class="pilula-poeta">Mateus estava trabalhando<br />quando ouviu um chamado.<br />A vida não parou para preparar o cenário.<br />Talvez seja assim também conosco.<br />Esperamos um grande momento,<br />uma placa,<br />uma certeza absoluta.<br />Mas algumas decisões chegam<br />no meio da rotina.<br />O chamado pode encontrar você<br />no trabalho,<br />em casa,<br />numa conversa,<br />num dia aparentemente comum.<br />A pergunta é simples:<br />quando a oportunidade de mudar aparecer,<br />você vai reconhecê-la?</div><hr /><p><strong>Reflexão:</strong> Que mudança importante pode estar sendo chamada para dentro da sua rotina?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-20-o-chamado-no-meio-da-rotina','O Chamado no Meio da Rotina | Pílula do Poeta','Algumas mudanças começam no lugar mais comum: no meio de um dia que parecia igual a todos os outros. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 25 / 40>',NULL,'o chamado no meio da rotina','O Chamado no Meio da Rotina | Pílula do Poeta','Algumas mudanças começam no lugar mais comum: no meio de um dia que parecia igual a todos os outros. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 25 / 40>','Arte da Pílula do Poeta 20: O Chamado no Meio da Rotina',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,20,'evaldo-poeta'),('evaldo-pilula-21-faca-novo-de-novo','Faça Novo de Novo','Colunas','Evaldo Poeta',NULL,'Recomeçar não apaga o que você viveu. Apenas impede que o passado tenha a última 
palavra.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Recomeçar não apaga o que você viveu. Apenas impede que o passado tenha a última 
palavra.</p><div class="pilula-poeta">Há dias em que tudo parece repetição.<br />Os mesmos erros,<br />as mesmas dúvidas,<br />as mesmas desculpas.<br />Mas um novo começo<br />não precisa esperar um novo ano.<br />Você pode revisar o caminho,<br />mudar uma escolha,<br />pedir perdão,<br />aprender algo,<br />começar novamente.<br />Fazer melhor não significa<br />nunca ter errado.<br />Significa não usar o erro<br />como desculpa para permanecer igual.<br />Hoje também pode ser<br />um ponto de virada.</div><hr /><p><strong>Reflexão:</strong> O que você pode fazer diferente a partir de hoje?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-21-faca-novo-de-novo','Faça Novo de Novo | Pílula do Poeta','Recomeçar não apaga o que você viveu. Apenas impede que o passado tenha a última palavra. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 27 / 40>',NULL,'faça novo de novo','Faça Novo de Novo | Pílula do Poeta','Recomeçar não apaga o que você viveu. Apenas impede que o passado tenha a última palavra. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 27 / 40>','Arte da Pílula do Poeta 21: Faça Novo de Novo',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,21,'evaldo-poeta'),('evaldo-pilula-22-rompa-a-multidao','Rompa a Multidão','Colunas','Evaldo Poeta',NULL,'Entre tantos pensamentos, medos e vozes, às vezes é preciso abrir caminho até aquilo 
em que você realmente acredita.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Entre tantos pensamentos, medos e vozes, às vezes é preciso abrir caminho até aquilo 
em que você realmente acredita.</p><div class="pilula-poeta">Há uma multidão dentro da mente:<br />medo, dúvida, comparação,<br />lembranças e possibilidades.<br />Alguns pensamentos empurram.<br />Outros puxam para trás.<br />Mas nem todo pensamento<br />precisa decidir seu próximo passo.<br />Romper a multidão<br />é reconhecer o que importa<br />e caminhar apesar do ruído.<br />Talvez a coragem não seja<br />ficar sem medo.<br />Talvez seja não deixar<br />que o medo escolha por você.</div><hr /><p><strong>Reflexão:</strong> Qual pensamento você precisa atravessar para chegar ao próximo passo?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-22-rompa-a-multidao','Rompa a Multidão | Pílula do Poeta','Entre tantos pensamentos, medos e vozes, às vezes é preciso abrir caminho até aquilo em que você realmente acredita. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 28 / 40>',NULL,'rompa a multidão','Rompa a Multidão | Pílula do Poeta','Entre tantos pensamentos, medos e vozes, às vezes é preciso abrir caminho até aquilo em que você realmente acredita. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 28 / 40>','Arte da Pílula do Poeta 22: Rompa a Multidão',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,22,'evaldo-poeta'),('evaldo-pilula-23-a-porta-esta-aberta','A Porta Está Aberta','Colunas','Evaldo Poeta',NULL,'Há oportunidades que não exigem força para entrar, apenas decisão.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Há oportunidades que não exigem força para entrar, apenas decisão.</p><div class="pilula-poeta">Uma porta aberta<br />não obriga ninguém a atravessar.<br />Ela apenas mostra que existe passagem.<br />Às vezes, pedimos uma oportunidade<br />e, quando ela chega,<br />começamos a procurar motivos para esperar.<br />O medo pergunta:<br />“E se der errado?”<br />A coragem pergunta:<br />“E se eu nunca tentar?”<br />Nem toda porta aberta<br />é a porta certa.<br />Mas toda decisão merece<br />ser tomada com consciência,<br />não apenas com medo.</div><hr /><p><strong>Reflexão:</strong> Que porta aberta você precisa avaliar com coragem e sabedoria?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-23-a-porta-esta-aberta','A Porta Está Aberta | Pílula do Poeta','Há oportunidades que não exigem força para entrar, apenas decisão. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 29 / 40>',NULL,'a porta está aberta','A Porta Está Aberta | Pílula do Poeta','Há oportunidades que não exigem força para entrar, apenas decisão. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 29 / 40>','Arte da Pílula do Poeta 23: A Porta Está Aberta',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,23,'evaldo-poeta'),('evaldo-pilula-24-troque-a-veste','Troque a Veste','Colunas','Evaldo Poeta',NULL,'Algumas fases da vida pedem que deixemos para trás aquilo que já não combina com 
quem estamos nos tornando.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Algumas fases da vida pedem que deixemos para trás aquilo que já não combina com 
quem estamos nos tornando.</p><div class="pilula-poeta">Há roupas que serviram ontem<br />e hoje apertam.<br />Há pensamentos que um dia protegeram<br />e agora impedem movimento.<br />Mudar não é rejeitar quem você foi.<br />É reconhecer que crescimento<br />também exige renovação.<br />Deixe algumas culpas,<br />alguns hábitos,<br />algumas palavras antigas<br />perderem o lugar de comando.<br />Talvez a mudança comece<br />quando você percebe:<br />não precisa continuar vestindo<br />uma identidade que já não representa você.</div><hr /><p><strong>Reflexão:</strong> O que você precisa deixar para trás para viver uma nova fase?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-24-troque-a-veste','Troque a Veste | Pílula do Poeta','Algumas fases da vida pedem que deixemos para trás aquilo que já não combina com quem estamos nos tornando. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 30 / 40>',NULL,'troque a veste','Troque a Veste | Pílula do Poeta','Algumas fases da vida pedem que deixemos para trás aquilo que já não combina com quem estamos nos tornando. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 30 / 40>','Arte da Pílula do Poeta 24: Troque a Veste',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,24,'evaldo-poeta'),('evaldo-pilula-25-conhecer-nao-basta','Conhecer Não Basta','Colunas','Evaldo Poeta',NULL,'Informação pode iluminar. Mas é a prática que transforma conhecimento em 
experiência.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Informação pode iluminar. Mas é a prática que transforma conhecimento em 
experiência.</p><div class="pilula-poeta">Você pode saber o que precisa fazer<br />e ainda assim continuar parado.<br />Pode conhecer o caminho,<br />ler sobre ele,<br />falar sobre ele<br />e nunca dar o primeiro passo.<br />Conhecimento sem prática<br />fica esperando na porta.<br />A mudança começa<br />quando aquilo que você entende<br />passa a aparecer nas suas escolhas.<br />Não pergunte apenas:<br />“Eu sei?”<br />Pergunte também:<br />“Eu estou fazendo?”</div><hr /><p><strong>Reflexão:</strong> Que conhecimento você já possui, mas ainda precisa transformar em atitude?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-25-conhecer-nao-basta','Conhecer Não Basta | Pílula do Poeta','Informação pode iluminar. Mas é a prática que transforma conhecimento em experiência. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 32 / 40>',NULL,'conhecer não basta','Conhecer Não Basta | Pílula do Poeta','Informação pode iluminar. Mas é a prática que transforma conhecimento em experiência. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 32 / 40>','Arte da Pílula do Poeta 25: Conhecer Não Basta',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,25,'evaldo-poeta'),('evaldo-pilula-26-levante-se','Levante-se','Colunas','Evaldo Poeta',NULL,'Há momentos em que o primeiro milagre da mudança é simplesmente sair da 
imobilidade.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Há momentos em que o primeiro milagre da mudança é simplesmente sair da 
imobilidade.</p><div class="pilula-poeta">Ficar no chão por um tempo<br />pode acontecer.<br />Transformar o chão em endereço<br />é outra história.<br />A espera pode ensinar,<br />mas também pode virar hábito.<br />Há coisas que ninguém poderá fazer por você:<br />dar o primeiro passo,<br />tomar uma decisão,<br />retomar uma responsabilidade.<br />Levantar não significa<br />que tudo ficou fácil.<br />Significa que você decidiu<br />não permanecer exatamente onde caiu.<br />Hoje, comece pequeno.<br />Mas comece.</div><hr /><p><strong>Reflexão:</strong> Qual é o menor passo que você pode dar hoje para sair da paralisia?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-26-levante-se','Levante-se | Pílula do Poeta','Há momentos em que o primeiro milagre da mudança é simplesmente sair da imobilidade. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 34 / 40>',NULL,'levante-se','Levante-se | Pílula do Poeta','Há momentos em que o primeiro milagre da mudança é simplesmente sair da imobilidade. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 34 / 40>','Arte da Pílula do Poeta 26: Levante-se',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,26,'evaldo-poeta'),('evaldo-pilula-27-vigie-o-que-voce-alimenta','Vigie o que Você Alimenta','Colunas','Evaldo Poeta',NULL,'Aquilo que entra repetidamente na mente também influencia o que sai pela boca e 
aparece nas escolhas.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Aquilo que entra repetidamente na mente também influencia o que sai pela boca e 
aparece nas escolhas.</p><div class="pilula-poeta">Palavras não são apenas sons.<br />Elas podem construir ambientes,<br />relações e pensamentos.<br />Por isso, vale observar<br />o que você repete,<br />o que consome,<br />o que alimenta.<br />Nem tudo que chega até você<br />merece permanecer dentro de você.<br />Vigiar não é viver com medo.<br />É escolher com consciência.<br />Cuide daquilo que você alimenta,<br />porque pensamentos repetidos<br />podem virar caminhos repetidos.</div><hr /><p><strong>Reflexão:</strong> Que palavra, conteúdo ou pensamento você precisa deixar de alimentar?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-27-vigie-o-que-voce-alimenta','Vigie o que Você Alimenta | Pílula do Poeta','Aquilo que entra repetidamente na mente também influencia o que sai pela boca e aparece nas escolhas. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 35 / 40>',NULL,'vigie o que você alimenta','Vigie o que Você Alimenta | Pílula do Poeta','Aquilo que entra repetidamente na mente também influencia o que sai pela boca e aparece nas escolhas. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 35 / 40>','Arte da Pílula do Poeta 27: Vigie o que Você Alimenta',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,27,'evaldo-poeta'),('evaldo-pilula-28-proteja-sua-mente','Proteja Sua Mente','Colunas','Evaldo Poeta',NULL,'Há batalhas que não começam no mundo. Começam na maneira como interpretamos o 
que acontece.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Há batalhas que não começam no mundo. Começam na maneira como interpretamos 
o que acontece.</p><div class="pilula-poeta">A mente precisa de cuidado.<br />Assim como uma casa,<br />ela também recebe visitas.<br />Algumas ideias entram<br />e trazem clareza.<br />Outras chegam<br />e deixam confusão.<br />Proteger a mente<br />não significa fugir da realidade.<br />Significa escolher<br />o que merece confiança,<br />o que precisa ser questionado<br />e o que deve ser deixado passar.<br />Cuide daquilo que ocupa<br />o espaço mais íntimo de você:<br />seus pensamentos.</div><hr /><p><strong>Reflexão:</strong> O que você precisa proteger melhor dentro da sua mente hoje?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-28-proteja-sua-mente','Proteja Sua Mente | Pílula do Poeta','Há batalhas que não começam no mundo. Começam na maneira como interpretamos o que acontece. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 37 / 40>',NULL,'proteja sua mente','Proteja Sua Mente | Pílula do Poeta','Há batalhas que não começam no mundo. Começam na maneira como interpretamos o que acontece. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 37 / 40>','Arte da Pílula do Poeta 28: Proteja Sua Mente',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,28,'evaldo-poeta'),('evaldo-pilula-29-comece-a-andar','Comece a Andar','Colunas','Evaldo Poeta',NULL,'Esperar ajuda pode ser necessário em alguns momentos. Mas existem passos que 
dependem da sua decisão.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Esperar ajuda pode ser necessário em alguns momentos. Mas existem passos que 
dependem da sua decisão.</p><div class="pilula-poeta">Há situações em que esperamos<br />que alguém venha nos mover.<br />Esperamos a oportunidade,<br />a aprovação,<br />a condição ideal.<br />Mas algumas mudanças<br />começam quando assumimos<br />a parte que nos pertence.<br />Você não controla tudo.<br />Mas pode escolher sua próxima atitude.<br />Talvez a pergunta não seja<br />“Quem vai me tirar daqui?”<br />Talvez seja:<br />“Qual é o passo que está nas minhas mãos?”<br />Comece com o que você pode.<br />O caminho pode aparecer depois.</div><hr /><p><strong>Reflexão:</strong> Qual responsabilidade está nas suas mãos hoje?</p><p><strong>Chamada para ação:</strong> Leia, reflita e compartilhe com alguém que precisa desta palavra hoje.</p>',NULL,'["Pílula do Poeta","Evaldo Poeta","reflexão","autoconhecimento","fé","vida","comportamento"]',NULL,NULL,'evaldo-pilula-29-comece-a-andar','Comece a Andar | Pílula do Poeta','Esperar ajuda pode ser necessário em alguns momentos. Mas existem passos que dependem da sua decisão. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 39 / 40>',NULL,'comece a andar','Comece a Andar | Pílula do Poeta','Esperar ajuda pode ser necessário em alguns momentos. Mas existem passos que dependem da sua decisão. Reflexão de Evaldo Poeta no PCH News. <PARSED TEXT FOR PAGE: 39 / 40>','Arte da Pílula do Poeta 29: Comece a Andar',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,29,'evaldo-poeta'),('evaldo-pilula-30-acalme-o-mar-interior','Acalme o Mar Interior','Colunas','Evaldo Poeta',NULL,'Nem toda tempestade pode ser evitada. Mas podemos aprender a atravessá-la sem 
entregar o comando ao medo.','27/09/2026','agora','published',0,'/brand/pilulas/pilula-do-poeta.svg','<p class="article-subtitle">Nem toda tempestade pode ser evitada. Mas podemos aprender a atravessá-la sem 
entregar o comando ao medo.</p><div class="pilula-poeta">O vento pode soprar forte.<br />O barco pode balançar.<br />E ainda assim,<br />a história não terminou.<br />Há dias em que o coração<br />parece navegar sem direção.<br />A preocupação faz ondas<br />antes mesmo de a realidade chegar.<br />A fé não promete ausência de tempestades.<br />Ela pode oferecer uma âncora<br />para atravessá-las.<br />Respire.<br />Olhe novamente.<br />Faça o que está ao seu alcance<br />e entregue a Deus aquilo que você não controla.<br />Nem todo mar calmo é sinal de paz.<br />Às vezes, paz é continuar firme<br />mesmo quando o mar se move.</div><hr /><p><strong>Reflexão:</strong> O que hoje está fora do seu controle e precisa ser entregue, em vez de carregado sozinho?</p><p><strong>Chamada para ação:</strong> </p>',NULL,'[]',NULL,NULL,'evaldo-pilula-30-acalme-o-mar-interior','Acalme o Mar Interior','Nem toda tempestade pode ser evitada. Mas podemos aprender a atravessá-la sem entregar o comando ao medo.',NULL,'acalme o mar interior','Acalme o Mar Interior','Nem toda tempestade pode ser evitada. Mas podemos aprender a atravessá-la sem entregar o comando ao medo.','Arte da Pílula do Poeta 30: Acalme o Mar Interior',false,now(),now(),'national',NULL,NULL,'Brasil','pt-BR',false,NULL,'Acervo editorial PCH News','pilula','{"fatoConfirmado":true,"fontesIdentificadas":true,"dadosConferidos":true,"contraditorioQuandoNecessario":true,"fatoOpiniaoSeparados":true,"tituloCorresponde":true,"aberturaEntregaRelevancia":true,"leitorLeigoEntende":true,"pchAcrescentaCompreensao":true,"chaveFinal":true,"comercialIdentificado":true,"imagemDireitoCredito":true,"revisaoFinal":true}',NULL,NULL,NULL,30,'evaldo-poeta')
